mapper.select:
SELECT dd.drink_detail_id AS drinkDetailId, dd.price FROM drink_details dd INNER JOIN drinks d ON d.drink_id = dd.drink_id INNER JOIN drink_categories dc ON dc.drink_category_id = d.drink_category_id WHERE dd.drink_detail_id IN
#{drinkDetailId}
AND dd.price >= 0 AND dd.deleted_at IS NULL AND d.deleted_at IS NULL AND d.is_deleted = FALSE AND d.status = 1 AND d.shop_id = #{shopId} AND dc.deleted_at IS NULL AND dc.is_deleted = FALSE AND dc.shop_id = #{shopId}

SELECT EXISTS (
SELECT 1 FROM shop_tables
WHERE table_id = #{tableId}
AND shop_id = #{shopId}
AND deleted_at IS NULL
AND is_deleted = FALSE
AND status = 1
)
